29	HixlPy::~HixlPy() {
30	  if (initialized_ && hixl_engine_ != nullptr) {
31	    py::gil_scoped_release release;
32	    hixl_engine_->Finalize();
33	    hixl_engine_.reset();
34	    initialized_ = false;
35	  }
36	}
