38	hixl::Status HixlPy::Initialize(const std::string &local_engine, const std::map<std::string, std::string> &options) {
39	  std::lock_guard<std::mutex> lock(mutex_);
40	  if (initialized_) {
41	    HIXL_LOGI("Initialize: already initialized, ignoring repeated call");
42	    return hixl::SUCCESS;
43	  }
44	  auto instance = std::make_unique<hixl::Hixl>();
45	  hixl::AscendString ascend_local_engine(local_engine.c_str());
46	  std::map<hixl::AscendString, hixl::AscendString> ascend_options;
47	  for (const auto &opt : options) {
48	    (void)ascend_options.emplace(opt.first.c_str(), opt.second.c_str());
49	  }
50	  hixl::Status ret = instance->Initialize(ascend_local_engine, ascend_options);
51	  if (ret != hixl::SUCCESS) {
52	    HIXL_LOGE(ret, "Initialize: failed for engine '%s'", local_engine.c_str());
53	    return ret;
54	  }
55	  hixl_engine_ = std::move(instance);
56	  initialized_ = true;
57	  return hixl::SUCCESS;
58	}
