60	void HixlPy::Finalize() {
61	  std::lock_guard<std::mutex> lock(mutex_);
62	  if (!initialized_ || hixl_engine_ == nullptr) {
63	    return;
64	  }
65	  hixl_engine_->Finalize();
66	  hixl_engine_.reset();
67	  initialized_ = false;
68	}
