70	std::pair<hixl::Status, uintptr_t> HixlPy::RegisterMem(const hixl::MemDesc &mem_desc, hixl::MemType mem_type) {
71	  hixl::MemHandle handle = nullptr;
72	  std::lock_guard<std::mutex> lock(mutex_);
73	  if (!initialized_ || hixl_engine_ == nullptr) {
74	    return {hixl::FAILED, reinterpret_cast<uintptr_t>(handle)};
75	  }
76	  hixl::Status ret = hixl_engine_->RegisterMem(mem_desc, mem_type, handle);
77	  return {ret, reinterpret_cast<uintptr_t>(handle)};
78	}
