227	  m.attr("UNSUPPORTED") = py::int_(hixl::UNSUPPORTED);
228	  m.attr("FAILED") = py::int_(hixl::FAILED);
229	  m.attr("RESOURCE_EXHAUSTED") = py::int_(hixl::RESOURCE_EXHAUSTED);
230	
231	  m.attr("OPTION_ENABLE_USE_FABRIC_MEM") = py::str(hixl::OPTION_ENABLE_USE_FABRIC_MEM);
