243	static void RegisterEnums(py::module_ &m) {
244	  py::enum_<hixl::MemType>(m, "MemType")
245	      .value("MEM_DEVICE", hixl::MEM_DEVICE)
246	      .value("MEM_HOST", hixl::MEM_HOST)
247	      .export_values();
248	
249	  py::enum_<hixl::TransferOp>(m, "TransferOp").value("READ", hixl::READ).value("WRITE", hixl::WRITE).export_values();
250	
251	  py::enum_<hixl::TransferStatus>(m, "TransferStatus")
252	      .value("WAITING", hixl::TransferStatus::WAITING)
253	      .value("COMPLETED", hixl::TransferStatus::COMPLETED)
254	      .value("TIMEOUT", hixl::TransferStatus::TIMEOUT)
255	      .value("FAILED", hixl::TransferStatus::FAILED);
256	
257	  py::enum_<hixl::AsyncConnectStatus>(m, "AsyncConnectStatus")
258	      .value("NOT_CONNECT", hixl::AsyncConnectStatus::NOT_CONNECT)
259	      .value("CONNECT_PENDING", hixl::AsyncConnectStatus::CONNECT_PENDING)
260	      .value("CONNECTING", hixl::AsyncConnectStatus::CONNECTING)
261	      .value("CONNECTED", hixl::AsyncConnectStatus::CONNECTED)
262	      .value("CONNECT_FAILED", hixl::AsyncConnectStatus::CONNECT_FAILED)
263	      .value("DISCONNECT_PENDING", hixl::AsyncConnectStatus::DISCONNECT_PENDING)
264	      .value("DISCONNECTING", hixl::AsyncConnectStatus::DISCONNECTING)
265	      .export_values();
266	
267	  py::enum_<hixl::FeatureType>(m, "FeatureType")
268	      .value("AUTO_CONNECT", hixl::AUTO_CONNECT)
269	      .value("CLIENT_SERVER_COMM", hixl::CLIENT_SERVER_COMM)
270	      .export_values();
271	}
272	
273	static void RegisterDataClasses(py::module_ &m) {
274	  py::class_<hixl::MemDesc>(m, "MemDesc")
275	      .def(py::init<uintptr_t, size_t>(), py::arg("addr"), py::arg("len"))
276	      .def_readwrite("addr", &hixl::MemDesc::addr)
277	      .def_readwrite("len", &hixl::MemDesc::len);
278	
279	  py::class_<hixl::TransferOpDesc>(m, "TransferOpDesc")
280	      .def(py::init<uintptr_t, uintptr_t, size_t>(), py::arg("local_addr"), py::arg("remote_addr"), py::arg("len"))
281	      .def_readwrite("local_addr", &hixl::TransferOpDesc::local_addr)
282	      .def_readwrite("remote_addr", &hixl::TransferOpDesc::remote_addr)
283	      .def_readwrite("len", &hixl::TransferOpDesc::len);
284	
285	  py::class_<hixl::TransferArgs>(m, "TransferArgs")
286	      .def(py::init<>())
287	      .def_property(
288	          "user_data", [](const hixl::TransferArgs &a) { return reinterpret_cast<uintptr_t>(a.user_data); },
289	          [](hixl::TransferArgs &a, uintptr_t v) { a.user_data = reinterpret_cast<const void *>(v); });
290	
291	  py::class_<hixl::GetTransferStatusArgs>(m, "GetTransferStatusArgs")
292	      .def(py::init<uint32_t, bool>(), py::arg("max_query_count") = UINT32_MAX, py::arg("skip_waiting") = false)
293	      .def_readwrite("max_query_count", &hixl::GetTransferStatusArgs::max_query_count)
294	      .def_readwrite("skip_waiting", &hixl::GetTransferStatusArgs::skip_waiting);
295	
296	  py::class_<hixl::TransferResult>(m, "TransferResult")
297	      .def(py::init<>())
298	      .def_property(
299	          "req", [](const hixl::TransferResult &r) { return reinterpret_cast<uintptr_t>(r.req); },
300	          [](hixl::TransferResult &r, uintptr_t v) { r.req = reinterpret_cast<hixl::TransferReq>(v); })
301	      .def_property(
302	          "user_data", [](const hixl::TransferResult &r) { return reinterpret_cast<uintptr_t>(r.user_data); },
303	          [](hixl::TransferResult &r, uintptr_t v) { r.user_data = reinterpret_cast<const void *>(v); })
304	      .def_readonly("status", &hixl::TransferResult::status);
305	
306	  py::class_<hixl::NotifyDesc>(m, "NotifyDesc")
307	      .def(py::init([](const std::string &name, const std::string &msg) {
308	             hixl::NotifyDesc n;
309	             n.name = hixl::AscendString(name.c_str());
310	             n.notify_msg = hixl::AscendString(msg.c_str());
311	             return n;
312	           }),
313	           py::arg("name"), py::arg("notify_msg"))
314	      .def_property(
315	          "name", [](const hixl::NotifyDesc &n) { return std::string(n.name.GetString()); },
316	          [](hixl::NotifyDesc &n, const std::string &s) { n.name = hixl::AscendString(s.c_str()); })
317	      .def_property(
318	          "notify_msg", [](const hixl::NotifyDesc &n) { return std::string(n.notify_msg.GetString()); },
319	          [](hixl::NotifyDesc &n, const std::string &s) { n.notify_msg = hixl::AscendString(s.c_str()); });
